// FUNCTION: BFME2 0x0037BC65 size=67 name=?rva0037BC65@Rva0037B7C7@@QAEXXZ evidence=?:placeholder tier=A
void RecorderClass::updatePlayback()
{
	UnsignedInt logicFrame = TheGameLogic->getFrame();
	cullBadCommands();
	if (m_nextFrame == (unsigned int)-1)
		return;
	if (m_doingAnalysis)
		logicFrame = m_nextFrame;
	if (m_nextFrame == logicFrame)
	{
		do
		{
			appendNextCommand();
			readNextFrame();
		} while (m_nextFrame == logicFrame);
	}
}

