// FUNCTION: BFME2 0x0037D42B size=307 name=?updateRecord@RecorderClass@@IAEXXZ evidence=N:ledger tier=A
void RecorderClass::updateRecord()
{
	Bool needFlush = FALSE;
	static Int lastFrame = -1;
	GameMessage *msg = TheCommandList->getFirstMessage();
	while (msg != NULL)
	{
		if (msg->getType() == GameMessage::MSG_NEW_GAME)
		{
			Int gameMode = msg->getArgument(0)->integer;
			if (gameMode == 4 || gameMode == 7 || TheGameLogic->m_unk0x114 != 3)
				return;
			if (gameMode != 1 && gameMode != 5)
				return;
			m_originalGameMode = msg->getArgument(0)->integer;
			lastFrame = 0;
			Int difficulty = 1;
			if (msg->getArgumentCount() >= 2)
				difficulty = msg->getArgument(1)->integer;
			Int rankPoints = 0;
			if (msg->getArgumentCount() >= 3)
				rankPoints = msg->getArgument(2)->integer;
			Int maxFPS = 0;
			if (msg->getArgumentCount() >= 4)
				maxFPS = msg->getArgument(3)->integer;

			startRecording(difficulty, m_originalGameMode, rankPoints, maxFPS);
		}
		else if (msg->getType() == GameMessage::MSG_CLEAR_GAME_DATA)
		{
			if (m_file != NULL)
			{
				lastFrame = -1;
				writeToFile(msg);
				stopRecording();
			}
			m_fileName.clear();
		}
		else if (m_file != NULL)
		{
			if (msg->getType() > GameMessage::MSG_BEGIN_NETWORK_MESSAGES && msg->getType() < GameMessage::MSG_END_NETWORK_MESSAGES)
			{
				// Only write the important messages to the file.
				writeToFile(msg);
				needFlush = TRUE;
			}
		}
		msg = msg->next();
	}

	if (needFlush)
	{
		fflush(m_file);
	}
}

